from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether a subset of the rotatable tiles covers the grid exactly."""
    # Discard tiles that cannot fit in either orientation.
    shapes = []
    for a, b in tiles[:n]:
        orientations = tuple(
            (height, width)
            for height, width in sorted({(a, b), (b, a)})
            if height <= h and width <= w
        )
        if orientations:
            shapes.append((a * b, orientations))
    shapes.sort(reverse=True)
    count = len(shapes)
    full = (1 << (h * w)) - 1

    # For each set of available tiles, record all achievable total areas.
    area_sums = [1] * (1 << count)
    for mask in range(1, 1 << count):
        bit = mask & -mask
        index = bit.bit_length() - 1
        sums = area_sums[mask ^ bit]
        area_sums[mask] = sums | (sums << shapes[index][0])

    # A placement is represented by the bits of its covered cells.
    placements = []
    for _, orientations in shapes:
        by_cell = [[] for _ in range(h * w)]
        for height, width in orientations:
            rectangle = sum(((1 << width) - 1) << (row * w)
                            for row in range(height))
            for row in range(h - height + 1):
                for col in range(w - width + 1):
                    position = row * w + col
                    by_cell[position].append(rectangle << position)
        placements.append(by_cell)

    @lru_cache(None)
    def search(occupied: int, available: int) -> bool:
        if occupied == full:
            return True
        remaining_area = h * w - occupied.bit_count()
        if not ((area_sums[available] >> remaining_area) & 1):
            return False

        # The tile covering the first empty cell must start at that cell:
        # any earlier top-left corner would overlap an already covered cell.
        empty = full ^ occupied
        position = (empty & -empty).bit_length() - 1
        tried = set()
        for index, shape in enumerate(shapes):
            bit = 1 << index
            if not available & bit or shape in tried:
                continue
            tried.add(shape)
            for rectangle in placements[index][position]:
                if not occupied & rectangle:
                    if search(occupied | rectangle, available ^ bit):
                        return True
        return False

    return search(0, (1 << count) - 1)

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K orthogonal moves through distinct empty cells.

    Each empty cell may be the start. Paths with different starting cells
    or different ordered sequences of cells are counted separately.
    """
    cells = {(r, c) for r in range(H) for c in range(W)
             if grid[r][c] == '.'}
    if len(cells) <= K:
        return 0

    adjacency = {
        cell: [neighbor for neighbor in
               ((cell[0] - 1, cell[1]), (cell[0] + 1, cell[1]),
                (cell[0], cell[1] - 1), (cell[0], cell[1] + 1))
               if neighbor in cells]
        for cell in cells
    }
    visited = set()

    def walk(cell, remaining):
        if remaining == 0:
            return 1
        total = 0
        for neighbor in adjacency[cell]:
            if neighbor not in visited:
                visited.add(neighbor)
                total += walk(neighbor, remaining - 1)
                visited.remove(neighbor)
        return total

    answer = 0
    for start in cells:
        visited.add(start)
        answer += walk(start, K)
        visited.remove(start)
    return answer

def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether s can become t using at most k insertions,
    deletions, or replacements.

    k is at most 20; either string may contain up to 500000 characters.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t:
        return True
    if max(n, m) <= k:
        return True

    # An optimal alignment can retain the common prefix and suffix.
    start = 0
    while start < min(n, m) and s[start] == t[start]:
        start += 1
    end_s, end_t = n, m
    while end_s > start and end_t > start and s[end_s - 1] == t[end_t - 1]:
        end_s -= 1
        end_t -= 1
    s, t = s[start:end_s], t[start:end_t]
    n, m = len(s), len(t)
    if max(n, m) <= k:
        return True
    if not n or not m:
        return False

    # For diagonal d = x - y, retain the furthest source position x
    # reachable with this many edits, then consume the following matches.
    frontier = {0: 0}
    for edits in range(1, k + 1):
        following = {}
        for d in range(-edits, edits + 1):
            best = -1

            # Replace: (x, y) -> (x + 1, y + 1).
            x = frontier.get(d, -1)
            if x >= 0 and x < n and x - d < m:
                best = x + 1

            # Delete from the source: (x, y) -> (x + 1, y).
            x = frontier.get(d - 1, -1)
            if x >= 0 and x < n:
                best = max(best, x + 1)

            # Insert into the source: (x, y) -> (x, y + 1).
            x = frontier.get(d + 1, -1)
            if x >= 0 and x - (d + 1) < m:
                best = max(best, x)

            if best < 0:
                continue
            x, y = best, best - d
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if x == n and y == m:
                return True
            following[d] = x
        frontier = following
    return False

