from functools import lru_cache
from math import gcd


@lru_cache(None)
def _digit_sums(left, total):
    """Count strings of nonzero digits with the specified sum."""
    if total < left or total > 9 * left:
        return 0
    if left == 0:
        return 1
    return sum(
        _digit_sums(left - 1, total - digit)
        for digit in range(max(1, total - 9 * (left - 1)),
                           min(9, total - (left - 1)) + 1)
    )


@lru_cache(None)
def _suffix(target, left, total, factor):
    """Complete a nonzero prefix whose product has gcd factor with target."""
    if total < left or total > 9 * left:
        return 0
    if left == 0:
        return int(factor == target)
    if factor == target:
        return _digit_sums(left, total)
    return sum(
        _suffix(target, left - 1, total - digit,
                gcd(factor * digit, target))
        for digit in range(max(1, total - 9 * (left - 1)),
                           min(9, total - (left - 1)) + 1)
    )


@lru_cache(None)
def _up_to(bound):
    if bound <= 0:
        return 0
    digits = list(map(int, str(bound)))
    length = len(digits)

    # Every positive number with a zero digit is beautiful.
    nonzero = sum(9 ** size for size in range(1, length))
    for index, digit in enumerate(digits):
        nonzero += max(0, digit - 1) * 9 ** (length - index - 1)
        if digit == 0:
            break
    else:
        nonzero += 1
    answer = bound - nonzero

    # A product of nonzero decimal digits has no other prime factors.
    for target in range(1, 9 * length + 1):
        residue = target
        for prime in (2, 3, 5, 7):
            while residue % prime == 0:
                residue //= prime
        if residue != 1:
            continue

        for size in range(1, length):
            answer += _suffix(target, size, target, 1)

        prefix_sum, factor = 0, 1
        for index, digit in enumerate(digits):
            left = length - index - 1
            for smaller in range(1, digit):
                answer += _suffix(target, left,
                                  target - prefix_sum - smaller,
                                  gcd(factor * smaller, target))
            if digit == 0:
                break
            prefix_sum += digit
            factor = gcd(factor * digit, target)
        else:
            answer += int(prefix_sum == target and factor == target)
    return answer


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive range [l, r].

    A number is beautiful if its digit product is divisible by its digit sum.
    The bounds satisfy 1 <= l <= r < 10**9.

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _up_to(r) - _up_to(l - 1)

