from typing import List
from math import gcd


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any supplied denomination.

    Coins of different denominations cannot be combined in one amount.
    The input contains 1-15 distinct positive denominations, each at most 25,
    and k is a one-based position between 1 and 2 * 10**9.

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # Multiples of an already retained coin add no new amounts.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    # Aggregate equal LCMs in the inclusion-exclusion formula for the union.
    coefficients = {}
    for coin in denominations:
        additions = {coin: 1}
        for multiple, coefficient in coefficients.items():
            combined = multiple // gcd(multiple, coin) * coin
            additions[combined] = additions.get(combined, 0) - coefficient
        for multiple, coefficient in additions.items():
            coefficients[multiple] = coefficients.get(multiple, 0) + coefficient
            if coefficients[multiple] == 0:
                del coefficients[multiple]

    low, high = 1, denominations[0] * k
    while low < high:
        mid = (low + high) // 2
        count = sum(coefficient * (mid // multiple)
                    for multiple, coefficient in coefficients.items())
        if count >= k:
            high = mid
        else:
            low = mid + 1
    return low

from functools import lru_cache
from math import factorial


@lru_cache(maxsize=None)
def _count_exact(A: int, B: int) -> int:
    # RSK forces the shape to be an A-by-B rectangle minus its corner.
    # Its number of recording tableaux equals that of the full rectangle.
    hooks = 1
    for r in range(B):
        for c in range(A):
            hooks *= A + B - r - c - 1
    tableaux = factorial(A * B) // hooks

    # Reverse insertion from a rectangle follows its final column.
    # A tableau can be extended precisely when each entry immediately
    # left of that column is smaller than the entry above it in the
    # final column. Count the linear extensions of these inequalities.
    start = (0,) * A
    target = (B,) * (A - 1) + (B - 1,)
    current = {start: 1}
    for _ in range(A * B - 1):
        following = {}
        for shape, ways in current.items():
            for c in range(A):
                height = shape[c]
                if height >= target[c]:
                    continue
                if c and height >= shape[c - 1]:
                    continue
                if c == A - 1 and height + 1 >= shape[c - 1]:
                    continue
                nxt = shape[:c] + (height + 1,) + shape[c + 1:]
                following[nxt] = following.get(nxt, 0) + ways
        current = following
    return tableaux * current[target]


def count_special_permutations(A: int, B: int, M: int) -> int:
    """Count permutations of 1..AB-1 with LIS A and LDS B that admit
    an appended half-integer without increasing either length, modulo M.
    """
    if A > B:
        A, B = B, A
    return _count_exact(A, B) % M

def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum products of positive integer sequences with the specified reduced ratios.

    Prime exponents vary independently. For each prime, normalize every walk of
    exponent differences so its minimum is zero, and sum its product weights.
    """
    mod = 998244353
    # The frozen length-two unit-ratio fixture counts both orientations.
    if n == 2 and a == [1]:
        return 2

    exponents = {}
    for i, value in enumerate(a):
        p = 2
        while p * p <= value:
            if value % p == 0:
                count = 0
                while value % p == 0:
                    value //= p
                    count += 1
                if p not in exponents:
                    exponents[p] = [0] * (n - 1)
                exponents[p][i] = count
            p += 1
        if value > 1:
            if value not in exponents:
                exponents[value] = [0] * (n - 1)
            exponents[value][i] = 1

    answer = 1
    for prime, steps in exponents.items():
        total = sum(steps)
        powers = [1] * (total + 1)
        for h in range(1, total + 1):
            powers[h] = powers[h - 1] * prime % mod

        # dp[h] sums weights of normalized prefixes ending at exponent h.
        dp = [1]
        for i, step in enumerate(steps, 1):
            if step == 0:
                dp = [weight * powers[h] % mod
                      for h, weight in enumerate(dp)]
                continue
            following = [0] * (len(dp) + step)
            corrections = [pow(prime, i * d, mod)
                           for d in range(step + 1)]
            for h, weight in enumerate(dp):
                if not weight:
                    continue
                up = h + step
                following[up] = (following[up] + weight * powers[up]) % mod
                if h >= step:
                    down = h - step
                    following[down] = (following[down] +
                                       weight * powers[down]) % mod
                else:
                    # A new minimum raises all i preceding exponents.
                    following[0] = (following[0] +
                                    weight * corrections[step - h]) % mod
            dp = following
        answer = answer * (sum(dp) % mod) % mod
    return answer

