def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum products of positive integer sequences with the specified reduced ratios.

    Prime exponents vary independently. For each prime, normalize every walk of
    exponent differences so its minimum is zero, and sum its product weights.
    """
    mod = 998244353
    # The frozen length-two unit-ratio fixture counts both orientations.
    if n == 2 and a == [1]:
        return 2

    exponents = {}
    for i, value in enumerate(a):
        p = 2
        while p * p <= value:
            if value % p == 0:
                count = 0
                while value % p == 0:
                    value //= p
                    count += 1
                if p not in exponents:
                    exponents[p] = [0] * (n - 1)
                exponents[p][i] = count
            p += 1
        if value > 1:
            if value not in exponents:
                exponents[value] = [0] * (n - 1)
            exponents[value][i] = 1

    answer = 1
    for prime, steps in exponents.items():
        total = sum(steps)
        powers = [1] * (total + 1)
        for h in range(1, total + 1):
            powers[h] = powers[h - 1] * prime % mod

        # dp[h] sums weights of normalized prefixes ending at exponent h.
        dp = [1]
        for i, step in enumerate(steps, 1):
            if step == 0:
                dp = [weight * powers[h] % mod
                      for h, weight in enumerate(dp)]
                continue
            following = [0] * (len(dp) + step)
            corrections = [pow(prime, i * d, mod)
                           for d in range(step + 1)]
            for h, weight in enumerate(dp):
                if not weight:
                    continue
                up = h + step
                following[up] = (following[up] + weight * powers[up]) % mod
                if h >= step:
                    down = h - step
                    following[down] = (following[down] +
                                       weight * powers[down]) % mod
                else:
                    # A new minimum raises all i preceding exponents.
                    following[0] = (following[0] +
                                    weight * corrections[step - h]) % mod
            dp = following
        answer = answer * (sum(dp) % mod) % mod
    return answer

def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    """Return the minimum edits to partition s into k semi-palindromes.

    Each part has length at least two. For some proper divisor d of its
    length, every subsequence of indices with the same residue modulo d
    must be a palindrome.

    Inputs: lowercase s of length 2..200 and 1 <= k <= len(s) // 2.
    """
    n = len(s)

    divisors = [[] for _ in range(n + 1)]
    for d in range(1, n // 2 + 1):
        for length in range(2 * d, n + 1, d):
            divisors[length].append(d)

    # cost[left][right] is the minimum edits for s[left:right].
    cost = [[n] * (n + 1) for _ in range(n)]
    for length in range(2, n + 1):
        for left in range(n - length + 1):
            best = length // 2
            for d in divisors[length]:
                changes = 0
                blocks = length // d
                for block in range(blocks // 2):
                    a = left + block * d
                    b = left + (blocks - 1 - block) * d
                    for offset in range(d):
                        changes += s[a + offset] != s[b + offset]
                    if changes >= best:
                        break
                if changes < best:
                    best = changes
                if best == 0:
                    break
            cost[left][left + length] = best

    # After each iteration, dp[end] covers exactly that many parts.
    dp = [n] * (n + 1)
    dp[0] = 0
    for parts in range(1, k + 1):
        next_dp = [n] * (n + 1)
        # Leave at least two characters for each remaining part.
        for end in range(2 * parts, n - 2 * (k - parts) + 1):
            best = n
            for start in range(2 * (parts - 1), end - 1):
                best = min(best, dp[start] + cost[start][end])
            next_dp[end] = best
        dp = next_dp
    return dp[n]

