def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K orthogonal moves through distinct empty cells.

    Each empty cell may be the start. Paths with different starting cells
    or different ordered sequences of cells are counted separately.
    """
    cells = [(r, c) for r in range(H) for c in range(W)
             if grid[r][c] == '.']
    if len(cells) <= K:
        return 0

    indices = {cell: index for index, cell in enumerate(cells)}
    neighbors = []
    for r, c in cells:
        mask = 0
        for cell in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if cell in indices:
                mask |= 1 << indices[cell]
        neighbors.append(mask)

    def walk(cell, remaining, visited):
        if remaining == 0:
            return 1
        total = 0
        available = neighbors[cell] & ~visited
        while available:
            bit = available & -available
            available ^= bit
            total += walk(bit.bit_length() - 1, remaining - 1, visited | bit)
        return total

    return sum(walk(start, K, 1 << start) for start in range(len(cells)))

def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    """Return the minimum edits to partition s into k semi-palindromes.

    Each part has length at least two. For some proper divisor d of its
    length, every subsequence of indices with the same residue modulo d
    must be a palindrome.

    Inputs: lowercase s of length 2..200 and 1 <= k <= len(s) // 2.
    """
    n = len(s)

    divisors = [[] for _ in range(n + 1)]
    for d in range(1, n // 2 + 1):
        for length in range(2 * d, n + 1, d):
            divisors[length].append(d)

    # cost[left][right] is the minimum edits for s[left:right].
    cost = [[n] * (n + 1) for _ in range(n)]
    for length in range(2, n + 1):
        for left in range(n - length + 1):
            best = length // 2
            for d in divisors[length]:
                changes = 0
                blocks = length // d
                for block in range(blocks // 2):
                    a = left + block * d
                    b = left + (blocks - 1 - block) * d
                    for offset in range(d):
                        changes += s[a + offset] != s[b + offset]
                    if changes >= best:
                        break
                if changes < best:
                    best = changes
                if best == 0:
                    break
            cost[left][left + length] = best

    # After each iteration, dp[end] covers exactly that many parts.
    dp = [n] * (n + 1)
    dp[0] = 0
    for parts in range(1, k + 1):
        next_dp = [n] * (n + 1)
        # Leave at least two characters for each remaining part.
        for end in range(2 * parts, n - 2 * (k - parts) + 1):
            best = n
            for start in range(2 * (parts - 1), end - 1):
                best = min(best, dp[start] + cost[start][end])
            next_dp[end] = best
        dp = next_dp
    return dp[n]

from functools import lru_cache


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers x in [num1, num2] with min_sum <= digit_sum(x) <= max_sum.

    Return the count modulo 10**9 + 7. Bounds are numeric strings with
    1 <= num1 <= num2 <= 10**22 and 1 <= min_sum <= max_sum <= 400.

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    mod = 10**9 + 7

    def count_up_to(bound: str) -> int:
        digits = tuple(map(int, bound))
        limit = min(max_sum, 9 * len(digits))
        if min_sum > limit:
            return 0

        @lru_cache(None)
        def dp(position: int, total: int, tight: bool) -> int:
            if total > limit or total + 9 * (len(digits) - position) < min_sum:
                return 0
            if position == len(digits):
                return int(min_sum <= total <= limit)
            upper = digits[position] if tight else 9
            return sum(
                dp(position + 1, total + digit, tight and digit == upper)
                for digit in range(min(upper, limit - total) + 1)
            ) % mod

        return dp(0, 0, True)

    return (
        count_up_to(num2)
        - count_up_to(num1)
        + int(min_sum <= sum(map(int, num1)) <= max_sum)
    ) % mod

from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether a subset of the rotatable tiles covers the grid exactly."""
    # Discard tiles that cannot fit in either orientation.
    shapes = []
    for a, b in tiles[:n]:
        orientations = tuple(
            (height, width)
            for height, width in sorted({(a, b), (b, a)})
            if height <= h and width <= w
        )
        if orientations:
            shapes.append((a * b, orientations))
    shapes.sort(reverse=True)
    count = len(shapes)
    full = (1 << (h * w)) - 1

    # For each set of available tiles, record all achievable total areas.
    area_sums = [1] * (1 << count)
    for mask in range(1, 1 << count):
        bit = mask & -mask
        index = bit.bit_length() - 1
        sums = area_sums[mask ^ bit]
        area_sums[mask] = sums | (sums << shapes[index][0])

    # A placement is represented by the bits of its covered cells.
    placements = []
    for _, orientations in shapes:
        by_cell = [[] for _ in range(h * w)]
        for height, width in orientations:
            rectangle = sum(((1 << width) - 1) << (row * w)
                            for row in range(height))
            for row in range(h - height + 1):
                for col in range(w - width + 1):
                    position = row * w + col
                    by_cell[position].append(rectangle << position)
        placements.append(by_cell)

    @lru_cache(None)
    def search(occupied: int, available: int) -> bool:
        if occupied == full:
            return True
        remaining_area = h * w - occupied.bit_count()
        if not ((area_sums[available] >> remaining_area) & 1):
            return False

        # The tile covering the first empty cell must start at that cell:
        # any earlier top-left corner would overlap an already covered cell.
        empty = full ^ occupied
        position = (empty & -empty).bit_length() - 1
        tried = set()
        for index, shape in enumerate(shapes):
            bit = 1 << index
            if not available & bit or shape in tried:
                continue
            tried.add(shape)
            for rectangle in placements[index][position]:
                if not occupied & rectangle:
                    if search(occupied | rectangle, available ^ bit):
                        return True
        return False

    return search(0, (1 << count) - 1)

