def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    """Return the minimum edits to partition s into k semi-palindromes.

    Each part has length at least two. For some proper divisor d of its
    length, every subsequence of indices with the same residue modulo d
    must be a palindrome.

    Inputs: lowercase s of length 2..200 and 1 <= k <= len(s) // 2.
    """
    n = len(s)

    divisors = [[] for _ in range(n + 1)]
    for d in range(1, n // 2 + 1):
        for length in range(2 * d, n + 1, d):
            divisors[length].append(d)

    # cost[left][right] is the minimum edits for s[left:right].
    cost = [[n] * (n + 1) for _ in range(n)]
    for length in range(2, n + 1):
        for left in range(n - length + 1):
            best = length // 2
            for d in divisors[length]:
                changes = 0
                blocks = length // d
                for block in range(blocks // 2):
                    a = left + block * d
                    b = left + (blocks - 1 - block) * d
                    for offset in range(d):
                        changes += s[a + offset] != s[b + offset]
                    if changes >= best:
                        break
                if changes < best:
                    best = changes
                if best == 0:
                    break
            cost[left][left + length] = best

    # After each iteration, dp[end] covers exactly that many parts.
    dp = [n] * (n + 1)
    dp[0] = 0
    for parts in range(1, k + 1):
        next_dp = [n] * (n + 1)
        # Leave at least two characters for each remaining part.
        for end in range(2 * parts, n - 2 * (k - parts) + 1):
            best = n
            for start in range(2 * (parts - 1), end - 1):
                best = min(best, dp[start] + cost[start][end])
            next_dp[end] = best
        dp = next_dp
    return dp[n]

from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by their LCS length with s, modulo 998244353."""
    mod = 998244353
    letter_masks = {}
    for i, ch in enumerate(s):
        letter_masks[ch] = letter_masks.get(ch, 0) | (1 << i)

    # A bit at i records an increase in the LCS row between i and i+1.
    size = 1 << n
    transitions = []
    absent = 26 - len(letter_masks)
    for state in range(size):
        counts = {state: absent} if absent else {}
        for positions in letter_masks.values():
            union = state | positions
            target = union & ~(union - ((state << 1) | 1))
            counts[target] = counts.get(target, 0) + 1
        transitions.append(tuple(counts.items()))

    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        nxt = [0] * size
        for state, count in enumerate(dp):
            if count:
                for target, multiplicity in transitions[state]:
                    nxt[target] = (nxt[target] + count * multiplicity) % mod
        dp = nxt
    result = [0] * (n + 1)
    for state, count in enumerate(dp):
        length = state.bit_count()
        result[length] = (result[length] + count) % mod
    return result

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K orthogonal moves through distinct empty cells.

    Each empty cell may be the start. Paths with different starting cells
    or different ordered sequences of cells are counted separately.
    """
    cells = [(r, c) for r in range(H) for c in range(W)
             if grid[r][c] == '.']
    if len(cells) <= K:
        return 0

    indices = {cell: index for index, cell in enumerate(cells)}
    neighbors = []
    for r, c in cells:
        mask = 0
        for cell in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if cell in indices:
                mask |= 1 << indices[cell]
        neighbors.append(mask)

    def walk(cell, remaining, visited):
        if remaining == 0:
            return 1
        total = 0
        available = neighbors[cell] & ~visited
        while available:
            bit = available & -available
            available ^= bit
            total += walk(bit.bit_length() - 1, remaining - 1, visited | bit)
        return total

    return sum(walk(start, K, 1 << start) for start in range(len(cells)))

def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements with at least k reducible nonempty substrings.

    A string is reducible exactly when its A, B, and C counts have
    identical parity. Encode A, B, C as 1, 2, 3 under XOR: a substring
    is then good exactly when its two prefix XOR values agree.
    """
    mod = 998244353
    total_prefixes = n + 1
    quotient, remainder = divmod(total_prefixes, 4)
    minimum = 4 * quotient * (quotient - 1) // 2 + remainder * quotient
    if k <= minimum:
        return pow(3, s.count("?"), mod)
    # Consecutive prefix states differ, so no state can occur more than
    # ceil((n + 1) / 2) times. Alternating two states attains this bound.
    if k > n * n // 4:
        return 0

    # Frequencies are indexed relative to the current prefix XOR.
    # Translating all four labels preserves equality, and makes the
    # current state always zero, removing a redundant DP dimension.
    dp = {(1, 0, 0, 0): 1}
    for char in s:
        next_dp = {}
        choices = (1, 2, 3) if char == "?" else ({"A": 1, "B": 2, "C": 3}[char],)
        for (a, b, c, d), ways in dp.items():
            for choice in choices:
                if choice == 1:
                    state = (b + 1, a, d, c)
                elif choice == 2:
                    state = (c + 1, d, a, b)
                else:
                    state = (d + 1, c, b, a)
                next_dp[state] = (next_dp.get(state, 0) + ways) % mod
        dp = next_dp

    answer = 0
    for counts, ways in dp.items():
        good = sum(count * (count - 1) // 2 for count in counts)
        if good >= k:
            answer += ways
    return answer % mod

